input.sparql:
SELECT ?zone ?zone_type ?label WHERE {
  ?zone a brick:Zone .
  ?zone brick:hasLabel ?label .
  FILTER(CONTAINS(?label, "Zone_F2"))
}

SELECT ?zone ?label WHERE {
  ?zone a brick:Zone .
  ?zone brick:hasLabel ?label .
  FILTER(contains(?label, "Core"))
}

